import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features by mean difference and t-statistic
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] > 0.8:  # Clinical or high effect size
            strong_features.append(fid)

    # Remove near-duplicates based on correlation
    to_remove = set()
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Keep only one feature from each correlated pair
    for (f1, f2), corr in correlations.items():
        if f1 in to_remove or f2 in to_remove:
            continue
        # Prefer the feature with higher mean difference
        idx1 = feats.column(f1)
        idx2 = feats.column(f2)
        diff1 = abs(np.mean(feats.x[feats.y==1, idx1]) - np.mean(feats.x[feats.y==0, idx1]))
        diff2 = abs(np.mean(feats.x[feats.y==1, idx2]) - np.mean(feats.x[feats.y==0, idx2]))
        if diff1 < diff2:
            to_remove.add(f1)
        else:
            to_remove.add(f2)

    # Filter features
    filtered_features = [f for f in strong_features if f not in to_remove]

    # If no mechanism, return empty design
    if len(filtered_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features by effect size
    selected_features = []
    for fid in filtered_features:
        idx = feats.column(fid)
        diff = abs(np.mean(feats.x[feats.y==1, idx]) - np.mean(feats.x[feats.y==0, idx]))
        selected_features.append((fid, diff))

    selected_features.sort(key=lambda x: x[1], reverse=True)
    drivers = tuple(f[0] for f in selected_features[:MAX_DRIVERS])

    # Build regression features (all selected except drivers for products)
    columns = tuple(f[0] for f in selected_features)

    # Look for interaction terms between top features
    products = []
    for i, f1 in enumerate(drivers):
        for j, f2 in enumerate(drivers):
            if i < j:
                products.append((f1, f2))

    # Simple weighted score using top feature
    loadings = {drivers[0]: 1.0} if drivers else {}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
